    #[test]
    fn a_symbol_layer_above_the_source_zoom_ceiling_is_selected_through_lazy_rebake() {
        // Reworked for lazy rebake-on-read: `refresh_plans_for_display_zoom`
        // (the eager bulk walk this called) is deleted -- see the design
        // note on `MapView::plan_for`. Same underlying property as the
        // original test this replaces: the three layers the reported bug
        // actually named (`building-number-label`, `crosswalks`,
        // `building-entrance`) are all `"type": "symbol"` layers, reaching
        // the screen through `match_tile_symbols` -> `symbol_cache` -> the
        // overlay pass in `paint()` -- a path `symbol_plan_for` now
        // gatekeeps. This drives that path through a real crossing,
        // asserting on what `symbol_plan_for` returns, with the tile's own
        // `z` pinned at 16 throughout -- only the camera's display zoom
        // crosses the layer's `min_zoom: Some(17)` bracket.
        let mut view = test_view_with_zoom_dependent_symbol_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 16.0;
        seed_baked_tile(&mut view, tile, decoded_tile_with_point_in_layer("housenum_label"));
        assert!(
            view.symbol_plan_for(tile).expect("a symbol plan must be baked").features.is_empty(),
            "below the layer's minzoom the symbol plan must select nothing"
        );
        assert_eq!(tile.z, 16, "the tile's own zoom must not change");

        view.camera_control.camera_mut().zoom = 18.0;
        assert_eq!(
            view.symbol_plan_for(tile).expect("a symbol plan must be baked").features.len(),
            1,
            "crossing the layer's minzoom must rebake the cached tile's symbol plan on read"
        );
        assert_eq!(tile.z, 16, "the tile's own zoom must not change");
    }

    #[test]
    fn display_zoom_follows_the_camera_past_the_sources_ceiling() {
        // `visible_tiles` clamps tile z to `source.max_zoom()` so we never
        // request a tile that would 404. `display_zoom` must NOT clamp -- that
        // conflation is the whole bug.
        let mut view = test_view_with_source_max_zoom(16);
        view.camera_control.camera_mut().zoom = 18.4;
        assert_eq!(view.display_zoom(), 18, "display zoom must track the camera, unclamped");
        assert!(
            view.visible_tiles(NO_GLOBE).iter().all(|t| t.z <= 16),
            "tile z must still be clamped to the source ceiling"
        );
    }

