    #[test]
    fn crossing_a_display_zoom_bucket_rebakes_the_cached_plan_on_read() {
        // Reworked for lazy rebake-on-read: `refresh_plans_for_display_zoom`
        // (bulk-rebaking every cached tile eagerly on every crossing --
        // measured at 0.654ms/tile, 335ms across MAX_VISIBLE_TILES=512
        // cached tiles) is deleted; see the design note on `plan_for`. A
        // tile decoded at one zoom keeps its plan forever unless something
        // rebakes it -- here that "something" is `plan_for`, invoked lazily
        // by the caller that actually needs the tile.
        let mut view = test_view_with_zoom_dependent_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 16.0;
        seed_baked_tile(&mut view, tile, decoded_tile_with_polygon_in_layer("housenum_label"));
        assert!(
            view.plan_for(tile).expect("a plan must be baked").ops.is_empty(),
            "below the layer's minzoom the plan must select nothing"
        );

        view.camera_control.camera_mut().zoom = 18.0;
        // The crossing read itself now returns the STALE bracket and queues
        // the rebake for the blocking pool -- `paint()` must never
        // tessellate (see `PlanOutcome::RebakeDeferred`). The rebake is what
        // carries the new zoom, so the property this test is about is
        // asserted on the read AFTER it lands, which is the read the real
        // `cx.notify()` provokes.
        assert!(
            view.plan_for(tile).expect("a plan must be baked").ops.is_empty(),
            "the crossing frame keeps drawing the bracket it already has"
        );
        assert_eq!(let_deferred_rebakes_land(&mut view), 1, "the crossing must have queued exactly one rebake");
        let plan = view.plan_for(tile).expect("a plan must be baked");
        assert_eq!(plan.ops.len(), 1, "crossing the layer's minzoom must rebake the cached tile's plan on read");
    }

    #[test]
    fn a_rebake_reuses_the_cached_match_instead_of_rematching_from_scratch() {
        // The point of the whole plan: crossing a bucket must not re-run the
        // filter pass. Assert on observable behaviour -- the resolved plan
        // is correct at the new zoom -- AND that the cached match was
        // reused, via `match_count` (see its field doc comment; same idea
        // as `LabelShapeCache::shape_count`).
        let mut view = test_view_with_zoom_dependent_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 16.0;
        seed_baked_tile(&mut view, tile, decoded_tile_with_polygon_in_layer("housenum_label"));
        assert_eq!(view.match_count, 1, "seeding the tile must match it exactly once");
        assert!(
            view.plan_for(tile).expect("a plan must be baked").ops.is_empty(),
            "below the layer's minzoom the plan must select nothing"
        );
        assert_eq!(view.match_count, 1, "reading within the same bucket must not re-match");

        view.camera_control.camera_mut().zoom = 18.0; // crosses the layer's minzoom (17)
        // The rebake runs on the blocking pool now, so it is
        // `let_deferred_rebakes_land` that performs it -- and `rebake_tile`
        // takes the `TileMatch` as an ARGUMENT rather than looking one up,
        // which is what makes the no-re-match property structural there
        // rather than merely observed. `match_count` must still not move.
        view.plan_for(tile).expect("a plan must be baked");
        assert_eq!(let_deferred_rebakes_land(&mut view), 1, "the crossing must have queued exactly one rebake");
        let plan = view.plan_for(tile).expect("a plan must be baked");
        assert_eq!(plan.ops.len(), 1, "crossing the layer's minzoom must rebake the plan, resolved fresh");
        assert_eq!(
            view.match_count, 1,
            "the rebake must resolve the SAME cached match at the new zoom, not re-run the filter pass"
        );
    }

    #[test]
    fn reading_the_same_tile_twice_in_one_display_zoom_bucket_bakes_once() {
        // Rebaking is bounded by "once per bucket, on the read that crosses
        // into it", not once per read. If this regresses, every single
        // frame that reads a tile re-bakes its plan even with no crossing
        // at all. `Arc::as_ptr` equality closes a gap a value comparison
        // alone can't: `put` always installs a fresh `Arc`, so even a
        // silent, same-valued rebake would swap the pointer. 18.0 and 18.9
        // floor to the same display zoom, so the second read must be a pure
        // cache hit that never touches `decoded_cache`/`style::resolve_plan`
        // again.
        let mut view = test_view_with_zoom_dependent_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 16.0;
        seed_baked_tile(&mut view, tile, decoded_tile_with_polygon_in_layer("housenum_label"));

        view.camera_control.camera_mut().zoom = 18.0;
        let plan_first_read = view.plan_for(tile).expect("a plan must be baked"); // crosses 16 -> 18: rebakes
        let ptr_after_first_read = Arc::as_ptr(&plan_first_read);

        view.camera_control.camera_mut().zoom = 18.9; // same bucket (floor 18) as the read above
        let plan_second_read = view.plan_for(tile).expect("a plan must be baked");
        let ptr_after_second_read = Arc::as_ptr(&plan_second_read);

        assert_eq!(
            ptr_after_first_read, ptr_after_second_read,
            "a second read within the same bucket must not rebake -- the Arc must be the same one"
        );
    }

    #[test]
    fn reading_one_tile_after_a_crossing_rebakes_only_that_tile() {
        // The whole point of lazy per-tile rebake: a crossing must not touch
        // every cached tile (that was the deleted eager
        // `refresh_plans_for_display_zoom` walk, measured at 0.654ms/tile --
        // 335ms/20 frames frozen across MAX_VISIBLE_TILES=512 cached
        // tiles). Only the tile actually read gets rebaked; everything else
        // stays at its old baked zoom until IT is read.
        let mut view = test_view_with_zoom_dependent_style();
        let read_tile = TileId { z: 16, x: 1, y: 1 };
        let untouched_tile = TileId { z: 16, x: 2, y: 1 };
        view.camera_control.camera_mut().zoom = 16.0;
        seed_baked_tile(&mut view, read_tile, decoded_tile_with_polygon_in_layer("housenum_label"));
        seed_baked_tile(&mut view, untouched_tile, decoded_tile_with_polygon_in_layer("housenum_label"));

        view.camera_control.camera_mut().zoom = 18.0; // crossing; nothing rebaked yet -- rebaking is lazy
        // Lazy AND off-thread now: the read queues the rebake and returns
        // the stale bracket, so the new zoom shows up on the read after the
        // pool lands it. The tile nobody read still queues nothing at all,
        // which is the property this test is really about.
        view.plan_for(read_tile).expect("a plan must be baked");
        assert_eq!(let_deferred_rebakes_land(&mut view), 1, "only the tile that was READ may queue a rebake");
        let plan = view.plan_for(read_tile).expect("a plan must be baked");
        assert_eq!(plan.ops.len(), 1, "the tile that was read must be rebaked at the new display zoom");

        let (untouched_baked_zoom, _, _) = view.cache.get(&untouched_tile).expect("untouched tile must still be cached");
        assert_eq!(
            *untouched_baked_zoom, 16,
            "a tile that was never read after the crossing must keep its old baked zoom"
        );
    }

    #[test]
    fn a_tile_panned_away_across_a_crossing_and_back_renders_at_the_new_zoom_not_the_old() {
        // The correctness property lazy rebake exists to preserve (see the
        // design note on `plan_for`): a tile decoded at zoom A, panned
        // off-screen, left through a crossing to zoom B while off-screen (so
        // nothing reads it and rebakes it), then panned back on-screen, must
        // render styled for B -- not still carrying A's styling. This is
        // exactly why narrowing the (deleted) eager walk to only visible
        // tiles was rejected as a fix: lazy rebake-on-read is what makes
        // skipping off-screen tiles safe.
        let mut view = test_view_with_zoom_dependent_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 16.0; // zoom A
        seed_baked_tile(&mut view, tile, decoded_tile_with_polygon_in_layer("housenum_label"));
        assert!(view.plan_for(tile).expect("a plan must be baked").ops.is_empty(), "styled for A, below minzoom");

        // Panned off-screen: simulated by simply not reading the tile again
        // while the crossing happens.
        view.camera_control.camera_mut().zoom = 18.0; // zoom B; tile is off-screen, nothing reads it here

        // Panned back on-screen: the first read since the crossing. It
        // queues the rebake rather than running it on the frame thread, and
        // the tile draws its A bracket for that frame -- the deliberate
        // trade in `PlanOutcome::RebakeDeferred`. What must NOT happen is
        // the tile staying at A: once the pool lands the rebake, the next
        // read renders at B.
        view.plan_for(tile).expect("a plan must still resolve after panning back");
        assert_eq!(let_deferred_rebakes_land(&mut view), 1, "panning back must queue the rebake the crossing skipped");
        let plan = view.plan_for(tile).expect("a plan must still resolve after panning back");
        assert_eq!(plan.ops.len(), 1, "must render at B (past the minzoom), not still carrying A's styling");
    }

    #[test]
    fn a_cached_plan_whose_decoded_tile_is_gone_yields_none_and_is_dropped() {
        // A plan cached at a stale zoom can only be rebaked from
        // `decoded_cache`. If that tile has since fallen out of
        // `decoded_cache` (evicted under memory pressure, capacity churn,
        // etc.), the plan can never be rebaked correctly again -- returning
        // it anyway would render stale styling with no way to ever correct
        // it. `plan_for` must drop the orphaned entry and return `None`,
        // letting the tile refetch through `ensure_visible_tiles_requested`'s
        // existing `decoded_cache.contains` check instead.
        let mut view = test_view_with_zoom_dependent_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 16.0;
        seed_baked_tile(&mut view, tile, decoded_tile_with_polygon_in_layer("housenum_label"));
        assert!(view.cache.contains(&tile), "sanity: the plan must actually be cached before this test's premise applies");

        view.decoded_cache.remove(&tile); // simulate the tile falling out of decoded_cache
        view.camera_control.camera_mut().zoom = 18.0; // crossing, so the cached plan is now stale

        assert_eq!(view.plan_for(tile), None, "a stale plan with no decoded tile to rebake from must not be returned");
        assert!(!view.cache.contains(&tile), "the orphaned stale entry must be dropped, not left to linger");
    }

    #[test]
    fn plan_for_bakes_a_tile_that_is_in_decoded_cache_but_never_reached_cache() {
        // Regression test for a hole `plan_for`'s original "not cached at
        // all -> None" case opened: `cache` and `decoded_cache` are
        // independent LRUs, written on different schedules (`cache` is
        // touched by every `plan_for` read across every visible tile every
        // frame; `decoded_cache` only on decode completion), so `cache` can
        // evict an entry `decoded_cache` still holds. If `plan_for` then
        // returns `None` for that tile instead of baking one, the tile
        // never draws -- and `ensure_visible_tiles_requested` skips
        // refetching it forever, because its `decoded_cache.contains(&tile)`
        // check is satisfied. The tile is permanently invisible, not just
        // until the next crossing. A tile with decoded data sitting right
        // there must always be able to produce a plan.
        let mut view = test_view_with_zoom_dependent_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 18.0; // above the layer's minzoom(17)
        // Simulates `cache` having independently evicted this tile's plan
        // while `decoded_cache` still holds it -- deliberately NOT using
        // `seed_baked_tile`, which would also populate `cache`.
        view.decoded_cache.put(tile, Arc::new(decoded_tile_with_polygon_in_layer("housenum_label")));
        assert!(!view.cache.contains(&tile), "sanity: this test's premise is an absent cache entry");

        let plan = view.plan_for(tile).expect("a tile with decoded data must always produce a plan");
        assert_eq!(plan.ops.len(), 1, "the baked plan must reflect the current display zoom");
        let (baked_zoom, _, _) = view.cache.get(&tile).expect("the fresh bake must be stored back into cache");
        assert_eq!(*baked_zoom, 18, "must be baked at the current display zoom");
    }

    #[test]
    fn symbol_plan_for_bakes_a_tile_that_is_in_decoded_cache_but_never_reached_symbol_cache() {
        // The `symbol_plan_for`/`symbol_cache` analog of
        // `plan_for_bakes_a_tile_that_is_in_decoded_cache_but_never_reached_cache`
        // -- same independent-LRU divergence, same permanent-invisibility
        // hole if left unfixed.
        let mut view = test_view_with_zoom_dependent_symbol_style();
        let tile = TileId { z: 16, x: 1, y: 1 };
        view.camera_control.camera_mut().zoom = 18.0; // above the layer's minzoom(17)
        view.decoded_cache.put(tile, Arc::new(decoded_tile_with_point_in_layer("housenum_label")));
        assert!(!view.symbol_cache.contains(&tile), "sanity: this test's premise is an absent symbol_cache entry");

        let plan = view.symbol_plan_for(tile).expect("a tile with decoded data must always produce a symbol plan");
        assert_eq!(plan.features.len(), 1, "the baked symbol plan must reflect the current display zoom");
        let (baked_zoom, _) = view.symbol_cache.get(&tile).expect("the fresh bake must be stored back into symbol_cache");
        assert_eq!(*baked_zoom, 18, "must be baked at the current display zoom");
    }

    /// Builds a standalone `MapView` whose style has a single fill layer
